class NotificationAssignment(NotificationSource):
    assignment: WakeAssignment
    activity: AssignmentActivity

    @classmethod
    def for_delivery(cls, original: CommittedDelivery, records) -> tuple[NotificationSource, ...]:
        """Classify receipt absence at the original read boundary, without minting one."""
        sources = []
        for recipient, decision in zip(original.audience.recipients, original.decisions, strict=True):
            matching = tuple(record for record in records
                if record.assignment.source == original.message.reference
                and record.assignment.recipient_lookup == recipient.recipient_lookup)
            if len(matching) > 1:
                raise ValueError("Original notification recipient has multiple handling receipts")
            sources.append(matching[0] if matching else UnrecordedNotificationSource(recipient, decision))
        return tuple(sources)

    @classmethod
    def database_path(cls, root: Path) -> Path:
        return root / "coordination.sqlite3"

    @classmethod
    def source_paths(cls, root: Path) -> tuple[Path, ...]:
        """SQLite may publish original recipient changes only in its WAL."""
        database = cls.database_path(root)
        return database, database.with_name(database.name + "-wal")

    @classmethod
    def select(
        cls,
        root: Path,
        predicate: str,
        parameters: tuple,
        *,
        limit: int = 0,
        ascending: bool = False,
    ):
        from .coordination_database import CoordinationStore
        from .native_runtime_input import NativeRuntimeInput
        from .recovery_projection import _preflight

        database = cls.database_path(root)
        failure = _preflight(database)
        if failure == "missing":
            return ()
        if failure:
            raise ValueError(f"Channel notification status unavailable: {failure}")
        with CoordinationStore.observing(database, lock_timeout=0.05) as connection:
            if SQLiteUserVersion.read(connection.execute("PRAGMA user_version")) != [
                SQLiteUserVersion(COORDINATION_SCHEMA_VERSION)
            ]:
                raise ValueError("Channel notification status has an unsupported schema")
            columns = ",".join(f"w.{name}" for name in WakeAssignment.columns())
            rows = WakeAssignment.joined(
                connection.execute(
                    f"SELECT {columns}, EXISTS (SELECT 1 FROM {NativeRuntimeInput.declared_name} n "
                    f"JOIN ({NativeRuntimeInput.source_membership_sql()}) member ON member.input_id=n.input_id "
                    "WHERE member.assignment_id=w.assignment_id "
                    "AND n.stage='triage' AND n.session_entry_id IS NULL) "
                    "AS triage_inflight, c.execution_id AS current_execution_id "
                    f"FROM {WakeAssignment.declared_name} w "
                    f"LEFT JOIN {CurrentExecutions.declared_name} c "
                    "ON c.owner_lookup=w.recipient_lookup "
                    f"WHERE {predicate} ORDER BY w.wire_seq {'ASC' if ascending else 'DESC'},w.recipient"
                    + (" LIMIT ?" if limit else ""),
                    (*parameters, limit) if limit else parameters,
                ),
                AssignmentActivity,
            )
            return tuple(cls(assignment, activity) for assignment, activity in rows)

    @property
    def recipient(self) -> FrozenRecipient:
        return FrozenRecipient(self.assignment.recipient_lookup, self.assignment.recipient)

    def project(self, observation: RecipientActivity) -> MessageNotification:
        return self.assignment.lifecycle.notification(
            self.recipient,
            observation=observation,
            updated_at_ms=self.assignment.updated_at_ms,
            triage_inflight=self.activity.triage_inflight,
            blocked_by_prior=self.activity.blocks(self.assignment),
        )

class MessageNotification:
    """Read-only display of one recipient's durable assignment decision."""

    window_limit: ClassVar[int] = 120
    recipient_identity: FrozenRecipient
    state: str
    detail: str
    priority: int = 3
    busy: bool = False
    message: Message | None = None
    displayed_to: tuple[ThreadIncarnation, ...] = ()

    @property
    def recipient(self) -> str:
        return self.recipient_identity.canonical_thread

    @classmethod
    def window(
        cls, root: Path, registry: Registration, log: WireLog, messages: Sequence[Message]
    ) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
        """Read one visible window's actual recipient outcomes; never schedule work.

        Display uses the coordinator's existing assignment decoder and lifecycle.
        A missing coordination store or absent row supplies no receipt. Errors remain
        visible to the caller instead of becoming false successful delivery.
        """
        if len(messages) > cls.window_limit:
            raise ValueError("Notification reads require a bounded visible message window")
        references = tuple(reference for message in messages
                           for reference in message.notification_references())
        sources = log.deliveries_for_references(references)
        projected = cls.delivery_window(root, registry, sources)
        return {(message.seq,message.message_id):projected.get((message.seq,message.message_id), ())
                for message in messages}

    @classmethod
    def references(
        cls, root: Path, registry: Registration, log: WireLog,
        references: Sequence[MessageReference],
    ) -> dict[tuple[int, str], tuple[MessageNotification, ...]]:
        """Borrow mounted references in the original bounded delivery windows."""
        result = {}
        for start in range(0, len(references), cls.window_limit):
            sources = log.deliveries_for_references(
                references[start : start + cls.window_limit]
            )
            result.update(cls.delivery_window(root, registry, sources))
        return result

    @classmethod
    def delivery_window(cls, root: Path, registry: Registration,
                        sources: Sequence[CommittedDelivery]):
        """Project the original frozen audience even before handling is recorded."""
        from .notification_assignment import NotificationAssignment

        if len(sources) > cls.window_limit:
            raise ValueError("Notification reads require a bounded visible message window")
        keys = {(source.message.seq, source.message.message_id) for source in sources}
        result: dict[tuple[int, str], list[MessageNotification]] = {key: [] for key in keys}
        if not keys:
            return {}
        placeholders = ",".join("?" for _ in keys)
        rows = NotificationAssignment.select(
            root, f"w.wire_seq IN ({placeholders})", tuple(key[0] for key in keys)
        )
        snapshot = registry.snapshot()
        from .agent_activity import AgentActivity

        agents = AgentActivity(root, registry)
        observations = agents.observe_recipients(
            (recipient for source in sources for recipient in source.audience.recipients),
            snapshot=snapshot,
        )
        reads = ReadLedger(root / ReadLedger.filename)
        document = reads.read()
        for source in sources:
            key = (source.message.seq, source.message.message_id)
            for outcome in NotificationAssignment.for_delivery(source, rows):
                observation = observations[outcome.recipient.recipient_lookup]
                notification = observation.after_inbox_read(
                    outcome.project(observation), source, reads, document, snapshot
                )
                result[key].append(
                    replace(
                        notification,
                        displayed_to=reads.displayed_recipient(
                            source.message,
                            notification.recipient_identity,
                            snapshot,
                            document=document,
                        ),
                    )
                )
        return {key: tuple(rows) for key, rows in result.items()}

    @classmethod
    def recent(
        cls, root: Path, registry: Registration, log: WireLog, name: str, *, limit: int = 5
    ) -> tuple[MessageNotification, ...]:
        """Recent assigned messages, including channel work, for one agent view.

        Reads the original assignments and source messages. This is not a DM
        delivery or a read acknowledgement, and never schedules another turn.
        """
        if not 1 <= limit <= 20:
            raise ValueError("Recent notification limit must be between 1 and 20")
        owner = registry.require(name)
        from .transcript_receipts import AssignedTranscriptSource

        sources = AssignedTranscriptSource.for_thread(root, owner, log).rows(limit=limit)
        return cls.for_sources(root, registry, owner, sources)

    @classmethod
    def for_sources(
        cls, root: Path, registry: Registration, owner: Thread, sources: Sequence[CommittedDelivery]
    ) -> tuple[MessageNotification, ...]:
        """Project outcomes from the caller's original certified source window."""
        from .bus_publication import stable_thread_lookup

        lookup = stable_thread_lookup(owner.created_at)
        projected = cls.delivery_window(root, registry, sources)
        return tuple(
            replace(notification, message=source.message)
            for source in sources
            for notification in projected[source.message.seq, source.message.message_id]
            if source.audience.sender_lookup == lookup
            or notification.recipient_identity.recipient_lookup == lookup
        )

